package com.kral.tkgs;
import android.app.Activity;
import android.os.Bundle;
import android.content.Intent;
import android.graphics.Color;
import android.view.View;
import android.widget.*;
import java.io.*;
import java.util.*;
public class MainActivity extends Activity {
 private static final int PICK=100,SAVE=101;
 private final ArrayList<String> names=new ArrayList<>(), urls=new ArrayList<>();
 private LinearLayout list; private TextView status; private EditText search;
 private TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(-1);t.setPadding(18,14,18,14);return t;}
 private Button button(String title,View.OnClickListener click){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setOnClickListener(click);return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);load();ScrollView sc=new ScrollView(this);sc.setBackgroundColor(Color.rgb(10,21,36));LinearLayout root=new LinearLayout(this);root.setPadding(16,24,16,16);root.setOrientation(1);sc.addView(root);TextView title=label("KRAL TKGS PRO",26);title.setTextColor(0xff26cdc5);root.addView(title);root.addView(label("Android kanal listesi yöneticisi",14));root.addView(button("M3U / TXT içe aktar",v->open()));root.addView(button("M3U dışa aktar",v->export()));root.addView(button("Alfabetik sırala",v->{sort();render();}));root.addView(button("Tekrarları temizle",v->{dedupe();render();}));search=new EditText(this);search.setSingleLine(true);search.setHint("Kanal ara");search.setTextColor(-1);search.setHintTextColor(0xffa0b4c2);root.addView(search);status=label("",14);root.addView(status);list=new LinearLayout(this);list.setOrientation(1);root.addView(list);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){} public void onTextChanged(CharSequence s,int st,int before,int count){render();}public void afterTextChanged(android.text.Editable e){}});setContentView(sc);render();}
 private void open(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK);}
 private void export(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("audio/x-mpegurl");i.putExtra(Intent.EXTRA_TITLE,"kral-kanallar.m3u");startActivityForResult(i,SAVE);}
 @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(c!=RESULT_OK||data==null)return;try{if(r==PICK){ArrayList<String> nn=new ArrayList<>(),uu=new ArrayList<>();try(BufferedReader reader=new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(data.getData()),"UTF-8"))){String line,pending=null;while((line=reader.readLine())!=null){line=line.trim();if(line.startsWith("#EXTINF")){int comma=line.indexOf(',');pending=comma>=0?line.substring(comma+1).trim():"Bilinmeyen kanal";}else if(!line.isEmpty()&&!line.startsWith("#")){if(pending!=null){nn.add(pending);uu.add(line);pending=null;}else if(line.contains("://")){nn.add(line);uu.add(line);}else{nn.add(line);uu.add("");}}}if(pending!=null){nn.add(pending);uu.add("");}}names.clear();urls.clear();names.addAll(nn);urls.addAll(uu);persist();render();}else if(r==SAVE){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){StringBuilder sb=new StringBuilder("#EXTM3U\n");for(int k=0;k<names.size();k++){sb.append("#EXTINF:-1,").append(names.get(k).replace("\n"," ")).append("\n");if(!urls.get(k).isEmpty())sb.append(urls.get(k)).append("\n");}out.write(sb.toString().getBytes("UTF-8"));}Toast.makeText(this,"Kaydedildi",Toast.LENGTH_SHORT).show();}}catch(Exception e){Toast.makeText(this,"Dosya hatası: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 private void sort(){ArrayList<Integer> idx=new ArrayList<>();for(int i=0;i<names.size();i++)idx.add(i);Collections.sort(idx,(a,b)->String.CASE_INSENSITIVE_ORDER.compare(names.get(a),names.get(b)));ArrayList<String> n=new ArrayList<>(),u=new ArrayList<>();for(int i:idx){n.add(names.get(i));u.add(urls.get(i));}names.clear();names.addAll(n);urls.clear();urls.addAll(u);persist();}
 private void dedupe(){HashSet<String> seen=new HashSet<>();for(int i=0;i<names.size();){String key=names.get(i).trim().toLowerCase(Locale.ROOT)+"|"+urls.get(i);if(!seen.add(key)){names.remove(i);urls.remove(i);}else i++;}persist();}
 private void persist(){try(DataOutputStream out=new DataOutputStream(openFileOutput("channels.dat",MODE_PRIVATE))){out.writeInt(names.size());for(int i=0;i<names.size();i++){out.writeUTF(names.get(i));out.writeUTF(urls.get(i));}}catch(Exception e){Toast.makeText(this,"Kaydetme hatası",Toast.LENGTH_SHORT).show();}}
 private void load(){try(DataInputStream in=new DataInputStream(openFileInput("channels.dat"))){int count=in.readInt();if(count<0||count>100000)throw new IOException("Invalid count");for(int i=0;i<count;i++){names.add(in.readUTF());urls.add(in.readUTF());}}catch(Exception ignored){}}
 private void render(){if(list==null)return;list.removeAllViews();status.setText("Toplam "+names.size()+" kanal • Gerçek TKGS uydu taraması henüz yok");String q=search.getText().toString().toLowerCase(new Locale("tr","TR"));int shown=0;for(String name:names){if(!name.toLowerCase(new Locale("tr","TR")).contains(q))continue;if(shown++>=250){list.addView(label("İlk 250 sonuç. Aramayla daraltın.",13));break;}TextView t=label(name,16);t.setBackgroundColor(shown%2==0?0xff152b3c:0xff102235);list.addView(t);}}
}
